-- ════════════════════════════════════════════════════════════════════════════
--  seed-landing.sql
--
--  Structure:
--    content_menu
--      landing            (existing — welcome card rewritten)
--      app_guide
--        ag_auth          (Sign In + Account)
--        ag_survey        (every survey interaction incl. Stats tab)
--        ag_backoffice    (Content + Files + Config + AI Import)
--      dev_guide
--        dg_running       (./run commands + adding a domain)
--        dg_architecture  (service stack, component tree, content, auth)
--        dg_layers        (inline TabPanel — no cards, just children)
--          dg_database      (schema, JSONB, UUIDs, pool — verbose)
--          dg_node_routes   (router, JWT middleware, writing routes — verbose)
--          dg_graphql       (schema assembly, resolvers, permissions — verbose)
--          dg_python        (FastAPI setup + calling from Node.js)
--          dg_frontend      (pages, routing, constants, Api.ts)
--        dg_component_ref (all shell + form components with screenshots)
--        dg_claude_code   (setup, CLAUDE.md, domain workflow, links)
--
--  UUID ranges:
--    Top-level pages ........... 00000000-0000-0000-0000-00000000001X / 002X
--    App Guide sub-pages ....... 001X
--    Auth cards ................ 011X
--    Survey cards .............. 012X  (0120–0124=tabs, 0125=stats)
--    Backoffice cards .......... 013X
--    Dev Guide sub-pages ....... 002X (incl. 0029=layers, 0030=claude_code)
--    GraphQL cards ............. 024X  (0240=intro, 0241=schema, 0242=resolvers, 0243=permissions, 0244=types)
--    Running cards ............. 021X
--    Database cards ............ 022X
--    Node.js Routes cards ...... 023X
--    Python cards .............. 025X  (0250=setup, 0251=calling, 0252=pipeline, 0253=analytics, 0254=csv)
--    Frontend cards ............ 026X
--    Architecture cards ........ 027X
--    Component Ref cards ....... 028X
--    Claude Code cards ......... 030X
-- ════════════════════════════════════════════════════════════════════════════


