-- ── App Guide › Auth ──────────────────────────────────────────────────────────

INSERT INTO components (id, name, type, data, options) VALUES

  ('00000000-0000-0000-0000-000000000110', 'ag_signin', 'contentHtmlImage', '{
    "html": "<h2>Sign In</h2><p>Navigate to <code>/signin</code> or click <strong>Sign In</strong> in the top-right header. Use the <code>ADMIN_EMAIL</code> and <code>ADMIN_PASSWORD</code> values from your <code>.env</code> file for the first login.</p><h3>Roles</h3><ul><li><strong>admin</strong> — full access to all pages including the Backoffice (Content, Files, Configuration)</li><li><strong>user</strong> — access to Surveys and Account only; Backoffice routes redirect to the landing page silently</li></ul><h3>Session behaviour</h3><p>The JWT is stored in <code>localStorage</code> under <code>auth_token</code> and decoded client-side on every render — no round-trip to verify role. On page load <code>AuthContext</code> calls <code>GET /api/me</code> to validate the token server-side. An expired, revoked, or tampered token is cleared automatically and the user is treated as logged out. Refreshing the browser keeps the session alive; closing the tab does not end it. The session ends when you click the log-out icon in the header or the JWT expires (configured via <code>JWT_EXPIRES_IN</code> in <code>.env</code>).</p>",
    "src": "http://localhost:3000/api/files/seed-app-signin.png/download-by-key",
    "alt": "Sign-in page"
  }', '{}'),

  ('00000000-0000-0000-0000-000000000111', 'ag_account', 'contentHtmlImage', '{
    "html": "<h2>Account</h2><p>Accessible from the person icon in the header at <code>/account</code>. Available to all authenticated users.</p><h3>Change Password</h3><p>Requires your current password for verification, then the new password (minimum 8 characters) entered twice. Validation runs client-side before the API call — mismatched passwords or length failures show an inline error without hitting the server. On success the form clears and you are ready to log in with the new password on your next session.</p><h3>User Management (admin only)</h3><p>A <code>DataTable</code> listing every registered user: email, role badge, active toggle, and creation date.</p><ul><li><strong>Create User</strong> — modal for email, initial password, and role (<code>admin</code> or <code>user</code>). The new user can log in immediately; they should change their password on first login.</li><li><strong>Role</strong> — change a user''s role inline via a dropdown. Takes effect on their next API call — the existing session token retains the old role until it expires or the user logs out and back in.</li><li><strong>Active toggle</strong> — deactivate a user without deleting their data. Deactivated accounts cannot log in but all their submitted survey answers and uploaded files are preserved.</li></ul>",
    "src": "http://localhost:3000/api/files/seed-app-account.png/download-by-key",
    "alt": "Account page with user management table"
  }', '{}')

ON CONFLICT (id) DO NOTHING;

