-- ── App Guide › Survey ────────────────────────────────────────────────────────

INSERT INTO components (id, name, type, data, options) VALUES

  ('00000000-0000-0000-0000-000000000120', 'survey_overview', 'contentHtml', '{
    "html": "<h2>Surveys</h2><p>Available to all authenticated users at <code>/folder/Surveys</code>. A survey is a tree of questions assembled through the Build tab and filled in through the Fill Form tab. Every answer is stored as a JSONB object keyed by the question UUID — not the question text — so responses remain queryable even after question labels are renamed or reordered.</p><h3>Left panel</h3><p>Two tabs: <strong>Surveys</strong> lists all available surveys; click one to load it on the right. <strong>Questions</strong> is a searchable library of every question across all surveys, useful for finding shared questions or bulk-browsing the question catalogue.</p><h3>Right panel</h3><p>Three tabs per selected survey: <strong>Fill Form</strong> renders a live form for submitting a response, <strong>Answers</strong> shows all submissions in a table, and <strong>Build</strong> manages the question tree.</p>"
  }', '{}'),

  ('00000000-0000-0000-0000-000000000121', 'survey_fill', 'contentHtmlImage', '{
    "html": "<h2>Fill Form</h2><p>Renders the survey as a live form using <code>FormRenderer</code> in survey mode. Each question type maps to a specific input:</p><ul><li><code>text</code> / <code>number</code> / <code>date</code> — standard HTML inputs with appropriate keyboard types</li><li><code>textarea</code> — multi-line free text</li><li><code>check</code> — checkbox (boolean answer)</li><li><code>select</code> — dropdown populated from child <code>option</code> nodes defined in the Build tab</li><li><code>scale</code> — a slider from the configured min to max value</li></ul><p>Submitting creates a row in <code>survey_answers</code> with the answer JSONB keyed by question UUID and the current timestamp. After a successful submission the form shows a confirmation message and a <strong>Fill Again</strong> button to start a new response immediately without reloading the page. The Fill Again button resets all form fields to empty.</p>",
    "src": "http://localhost:3000/api/files/seed-app-surveys-fill.png/download-by-key",
    "alt": "Surveys Fill Form tab with a live form"
  }', '{}'),

  ('00000000-0000-0000-0000-000000000122', 'survey_answers', 'contentHtmlImage', '{
    "html": "<h2>Answers</h2><p>A <code>DataTable</code> listing every submission for the selected survey. Columns are labelled by question text; the table reconstructs itself from the question tree each time it loads, so renaming a question updates the column header immediately.</p><h3>Controls</h3><ul><li><strong>Text filter</strong> — searches across all answer values in real time</li><li><strong>Date filter</strong> — a date-range picker to narrow submissions by timestamp</li><li><strong>Export CSV</strong> — downloads all visible rows as a UTF-8 CSV file, respecting active filters</li><li><strong>Edit</strong> (per row) — re-opens the Fill Form pre-filled with that response; saving updates the existing answer record rather than creating a new one</li><li><strong>Delete</strong> (per row) — removes the submission after a confirmation prompt; cannot be undone</li></ul><p>The raw JSONB for each answer row uses question UUIDs as keys. The table layer resolves these to human-readable labels at display time.</p>",
    "src": "http://localhost:3000/api/files/seed-app-surveys-answers.png/download-by-key",
    "alt": "Surveys Answers tab with DataTable"
  }', '{}'),

  ('00000000-0000-0000-0000-000000000123', 'survey_build', 'contentHtmlImage', '{
    "html": "<h2>Build</h2><p>A <code>TreeEditor</code> for the question tree. The root node is always type <code>survey</code> — it holds the survey title and acts as a container for all questions.</p><h3>Adding questions</h3><p>Click <strong>Add Question</strong> on any node to insert a child at that level. Set the question type from the dropdown and write the label (this becomes the column header in the Answers table and the field label in the Fill Form). For <code>scale</code> questions also set min and max values. For <code>select</code> questions add child <code>option</code> nodes — each option needs a label that becomes one choice in the dropdown.</p><h3>Editing and reordering</h3><p>Click any node to open its edit form in a modal. Drag the handle on the left edge of a node to reorder it among its siblings. Position is persisted to <code>survey_components_relationships</code> immediately on drop. Use the delete button (trash icon) to remove a node and all its descendants after confirmation.</p><h3>Linked questions</h3><p>From the Questions library, a question can be linked into multiple surveys using the Link action. Linked questions are shared — editing the question text updates it everywhere it appears. This is useful for standard demographic or consent questions that appear across surveys.</p>",
    "src": "http://localhost:3000/api/files/seed-app-surveys-build.png/download-by-key",
    "alt": "Surveys Build tab with TreeEditor"
  }', '{}'),

  ('00000000-0000-0000-0000-000000000124', 'survey_questions', 'contentHtmlImage', '{
    "html": "<h2>Questions Library</h2><p>The <strong>Questions</strong> tab in the left panel lists every question node across all surveys. It is useful for auditing the question catalogue, finding questions to link into a new survey, or checking where a shared question is used.</p><h3>Filters</h3><ul><li><strong>Text search</strong> — filters by question label in real time as you type; clears immediately when the input is cleared</li><li><strong>Type filter</strong> — a dropdown to show only questions of a given type: <code>text</code>, <code>number</code>, <code>date</code>, <code>textarea</code>, <code>check</code>, <code>select</code>, or <code>scale</code></li></ul><p>Both filters apply simultaneously. Clicking a question in the library loads its edit form in the right panel. Any changes made there update the question globally — in every survey it belongs to.</p>",
    "src": "http://localhost:3000/api/files/seed-app-surveys-questions.png/download-by-key",
    "alt": "Surveys Questions library tab"
  }', '{}')

ON CONFLICT (id) DO NOTHING;

