-- ── App Guide › Backoffice ────────────────────────────────────────────────────

INSERT INTO components (id, name, type, data, options) VALUES

  ('00000000-0000-0000-0000-000000000130', 'bo_content', 'contentHtmlImage', '{
    "html": "<h2>Content</h2><p>Admin-only at <code>/folder/Content</code>. Manages the content tree that powers the public landing page. Every change is live immediately — no cache to clear, no rebuild needed.</p><h3>Left panel — Pages</h3><p>Lists all <code>contentPage</code> nodes. Select a page to load its tree on the right. Click <strong>+ New Page</strong> to create a new page (provide an internal name used as the DB identifier and a display text shown in the nav). A page only appears in the public nav when it is linked under <code>content_menu</code> — this linking happens through the Build tab of the content_menu page itself.</p><h3>Left panel — Cards</h3><p>A global library of every card across all pages, searchable by name and filterable by type (<code>contentHtml</code>, <code>contentImage</code>, <code>contentHtmlImage</code>). Clicking a card loads it for editing.</p><h3>Right panel — Build</h3><p>A <code>TreeEditor</code> for the selected page. <strong>Add</strong> opens a modal where you choose the card type: <em>HTML Text</em> (rich editor), <em>Image</em> (MinIO file picker), <em>HTML + Image</em> (two-column layout), <em>LaTeX</em> (KaTeX math rendering), or <em>Sub-page</em> (nests a child <code>contentPage</code>). Drag to reorder. Deleting a card removes it from the DB permanently.</p><h3>Right panel — Preview</h3><p>Live render using the same <code>ContentRenderer</code> as the public landing page, with admin edit and delete overlays on each card. Use this to verify layout and content before sharing with users.</p>",
    "src": "http://localhost:3000/api/files/seed-app-content-build.png/download-by-key",
    "alt": "Content page Build tab"
  }', '{}'),

  ('00000000-0000-0000-0000-000000000131', 'bo_files', 'contentHtmlImage', '{
    "html": "<h2>Files</h2><p>Admin-only at <code>/folder/Files</code>. Binary file storage backed by MinIO. File metadata (filename, MIME type, size, uploader, description) is tracked in the <code>files</code> Postgres table; the binary data lives in the MinIO <code>uploads</code> bucket.</p><h3>Left panel</h3><p>Searchable list of all uploaded files with filename, size, and MIME type badge. Click <strong>Upload</strong> in the top-right to open a file picker — the file is streamed to MinIO and a metadata row is created immediately. There is no size limit imposed by the app (MinIO limits apply).</p><h3>Right panel — Preview</h3><p>Renders the selected file inline: images as <code>&lt;img&gt;</code>, PDFs in an <code>&lt;iframe&gt;</code>, plain text and code files in a <code>&lt;pre&gt;</code> block, all other types as a download link. Useful for verifying uploads without leaving the app.</p><h3>Right panel — Details</h3><p>Shows filename, MIME type, size, upload date, and uploader email. The <strong>description</strong> field is editable via an inline <code>FormRenderer</code> form — useful for tagging files with context. <strong>Copy URL</strong> copies the file''s MinIO download URL to the clipboard. Paste this URL as the <code>src</code> in a <code>contentImage</code> or <code>contentHtmlImage</code> card to embed the file in a landing page card.</p>",
    "src": "http://localhost:3000/api/files/seed-app-files.png/download-by-key",
    "alt": "Files page with file selected"
  }', '{}'),

  ('00000000-0000-0000-0000-000000000132', 'bo_config', 'contentHtmlImage', '{
    "html": "<h2>Configuration</h2><p>Admin-only at <code>/folder/Configuration</code>. Manages the component trees that drive every dynamic form in the app — from the survey question editor forms to the domain feature forms. <strong>Changes here affect live forms across the entire application immediately.</strong></p><h3>Left panel</h3><p>Component list filtered by type: <code>form</code>, <code>input</code>, <code>select</code>, <code>check</code>, <code>plot</code>, <code>plotGrid</code>. Choose a type to load all matching root nodes. <strong>New Component</strong> creates a fresh standalone root node of the selected type.</p><h3>Edit lock</h3><p>The right panel opens in read-only mode by default — shown by a padlock icon in the header. Click the padlock to toggle editing. This intentional friction prevents accidental changes to forms that are actively used by running features. Always verify via the Preview tab after making changes.</p><h3>Right panel — Edit</h3><p>A <code>TreeEditor</code> for the component tree. <strong>Add</strong> inserts a child node: set its type, <code>data.text</code> (the label shown to the user in the rendered form), and <code>options.label</code> (the dot-path key <code>FormRenderer</code> uses to read and write the value — e.g. <code>patient.age</code>). <strong>Link</strong> attaches a shared existing node without duplicating it.</p><h3>Right panel — Preview</h3><p>Renders the tree as a live <code>FormRenderer</code> form in app mode. Verify field types, labels, and layout before wiring the form into a domain page.</p>",
    "src": "http://localhost:3000/api/files/seed-app-config.png/download-by-key",
    "alt": "Configuration page with tree editor"
  }', '{}'),

  ('00000000-0000-0000-0000-000000000133', 'bo_ai_import', 'contentHtmlImage', '{
    "html": "<h2>AI Import</h2><p>Available on the Content page under the <strong>AI Import</strong> tab. Lets you convert existing documents — LaTeX manuscripts, research papers, PDFs exported as images — into structured content cards using Claude. No manual copy-pasting or reformatting required.</p><h3>Workflow</h3><ol><li><strong>Enter your API key</strong> — paste your Anthropic API key into the field at the top of the tab (get one at <a href=\"https://console.anthropic.com\" target=\"_blank\">console.anthropic.com</a>). The key is saved to <code>localStorage</code> and persists across sessions.</li><li><strong>Upload</strong> — attach one or more <code>.tex</code> files or images. The upload is sent to the Node.js backend, which forwards it to Claude along with a system prompt instructing it to produce ManuSpine content cards.</li><li><strong>Review</strong> — Claude''s response appears as a preview using <code>ContentRenderer</code>. Each card is rendered exactly as it will look on the landing page.</li><li><strong>Refine</strong> — type a follow-up instruction (e.g. ''make the introduction shorter'', ''split the methods section into two cards'', ''add a LaTeX equation for the model''). Claude continues the conversation with full context of the previous draft.</li><li><strong>Save</strong> — when the draft looks correct, name the target page and click Save. The cards are written to the DB and linked under the chosen content page immediately.</li></ol><h3>Notes</h3><p>No server configuration needed — each user brings their own key. The conversation history is persisted in <code>localStorage</code> so the session survives page refreshes, useful for long editing sessions. Use <strong>Clear session</strong> before starting a new import.</p>",
    "src": "http://localhost:3000/api/files/seed-app-content-ai.png/download-by-key",
    "alt": "Content AI Import tab"
  }', '{}')

ON CONFLICT (id) DO NOTHING;

