-- ── Dev Guide › Running ───────────────────────────────────────────────────────

INSERT INTO components (id, name, type, data, options) VALUES

  ('00000000-0000-0000-0000-000000000210', 'dg_run_commands', 'contentHtml', '{
    "html": "<h2>Running the Project</h2><p>All services are managed with the <code>./run</code> shell script from the repo root. Never use raw <code>docker compose</code> commands — <code>./run</code> reads the <code>UID</code> and <code>GID</code> of the current user and passes them as build args so that files written inside containers are owned by you, not root.</p><pre style=\"background:rgba(0,0,0,0.08);padding:14px;border-radius:6px;overflow-x:auto;font-size:0.85em;line-height:1.7\"><code>cp .env.example .env        # copy the env template and fill in your values\n./run                       # build images (first time) and start all services\n./run rebuild &lt;service&gt;    # rebuild a service image after Dockerfile changes\n./run reset                 # wipe DB + MinIO volumes and restart from scratch\n./run rebuild-reset &lt;svc&gt;  # rebuild image AND wipe DB (combine both)\n./run down                  # stop all running containers</code></pre><p>On first start Postgres runs every SQL file in <code>init-scripts/</code> alphabetically on a fresh volume. The admin user is created in Node.js at startup from <code>ADMIN_EMAIL</code> and <code>ADMIN_PASSWORD</code> in your <code>.env</code>. Node.js also seeds MinIO with the screenshots from <code>pwa/public/screenshots/</code> so content cards can reference them by key.</p><p>Service URLs: Frontend <code>http://localhost:8100</code> · GraphQL playground <code>http://localhost:3000/graphql</code> · Python <code>http://localhost:5000</code>.</p>"
  }', '{}'),

  ('00000000-0000-0000-0000-000000000211', 'dg_add_domain', 'contentHtml', '{
    "html": "<h2>Adding a Domain</h2><p>A domain is a vertical slice of feature-level functionality — a patient registry, a billing module, a document store. Each domain adds five files in predictable locations. Mark every addition with the comment <code>// [MY DOMAIN]</code> (or <code>-- [MY DOMAIN]</code> in SQL) so all domain-specific code can be found by a single grep and cleanly removed when extracting the framework for a new project.</p><ol><li><strong>DB migration</strong> — <code>init-scripts/02-init-&lt;domain&gt;.sql</code><br/>Postgres picks this up alphabetically after the framework schema (<code>01-init-db.sql</code>). Run <code>./run reset</code> to apply it on a fresh volume.</li><li><strong>Node.js REST routes</strong> — <code>nodejs/routes/&lt;domain&gt;/things.js</code><br/>Register it in <code>backend.js</code> with <code>server.use(''/api'', require(''./routes/&lt;domain&gt;/things''));</code></li><li><strong>GraphQL resolvers</strong> — <code>nodejs/schema/resolvers/&lt;domain&gt;/things.js</code><br/>Spread it into <code>Query</code> and <code>Mutation</code> in <code>schema/index.js</code>.</li><li><strong>Python FastAPI routes</strong> (optional) — <code>python/api/domains/&lt;domain&gt;/routes.py</code><br/>Include the router in <code>python/api/main.py</code>.</li><li><strong>React pages</strong> — <code>pwa/src/pages/&lt;domain&gt;/</code><br/>Add constants in <code>constants.ts</code>, routes in <code>App.tsx</code>, and nav entries in <code>Menu.tsx</code>.</li></ol><p>Hardcode UUIDs in any seed SQL that is referenced by name from <code>constants.ts</code> (e.g. <code>FORM_ID</code>, <code>EDITOR_ID</code>). If the seed row moves or is regenerated with a new UUID, the frontend constant pointing to it will silently fetch nothing.</p>"
  }', '{}')

ON CONFLICT (id) DO NOTHING;

INSERT INTO components_relationships (parent_id, child_id, position) VALUES
  ('00000000-0000-0000-0000-000000000021', '00000000-0000-0000-0000-000000000210', 0),
