-- ── Dev Guide › Database ──────────────────────────────────────────────────────

INSERT INTO components (id, name, type, data, options) VALUES

  ('00000000-0000-0000-0000-000000000220', 'db_init_scripts', 'contentHtml', '{
    "html": "<h2>Init Scripts and Schema</h2><p>Postgres runs every <code>.sql</code> file in <code>init-scripts/</code> in alphabetical order on a fresh volume. This means naming is load order: <code>01-init-db.sql</code> runs first and creates the framework tables (components, surveys, users, files), then <code>02-init-&lt;domain&gt;.sql</code> adds domain tables, then seed files populate initial data.</p><pre style=\"background:rgba(0,0,0,0.08);padding:14px;border-radius:6px;overflow-x:auto;font-size:0.85em;line-height:1.7\"><code>-- init-scripts/02-init-myapp.sql\nCREATE TABLE my_things (\n  id         UUID        PRIMARY KEY DEFAULT gen_random_uuid(),\n  name       TEXT        NOT NULL,\n  data       JSONB       NOT NULL DEFAULT ''{}''::jsonb,\n  created_by UUID        REFERENCES users(id),\n  created_at TIMESTAMPTZ DEFAULT now()\n);</code></pre><p><strong>id UUID DEFAULT gen_random_uuid()</strong> — every row gets a unique UUID automatically on INSERT. Never use SERIAL integers; UUIDs are safe to generate client-side, safe across distributed systems, and safe to hardcode in seeds without collision risk.</p><p><strong>REFERENCES users(id)</strong> — a foreign key to the users table. Postgres enforces referential integrity: inserting a created_by that doesn''t exist in users fails at the DB layer, not the application layer.</p><p><strong>There are no ALTER TABLE migrations.</strong> In development, change the schema file and run <code>./run reset</code> to apply it on a fresh volume. Production migrations are a separate concern handled outside the framework.</p>"
  }', '{}'),

  ('00000000-0000-0000-0000-000000000221', 'db_jsonb', 'contentHtml', '{
    "html": "<h2>The JSONB Pattern</h2><p>The <code>components</code> table stores UI node configuration in two JSONB columns: <code>data</code> and <code>options</code>. This is the most important design decision in the framework and it is worth understanding why.</p><h3>Why JSONB instead of typed columns?</h3><p>A component tree node can be a form container, a text input, a select dropdown, a plot, a file picker, or a rich-text editor. Each type needs different configuration: a text input needs a placeholder, a select needs its option list, a plot needs axis labels and data keys. If you modelled each type with its own SQL columns you would need either a sparse wide table with dozens of nullable columns, or a dozen separate tables with a union query to fetch them all. Both are painful to extend when you add a new type.</p><p>JSONB solves this by giving each node a flexible schema-less bag for its type-specific data. Adding a new node type requires no DB migration — just agree on a JSON shape and update the renderer.</p><h3>data vs options</h3><ul><li><code>data</code> — user-facing values: the label text the user sees, the HTML content, the image URL, the selected value. This is what <code>FormRenderer</code> reads and writes.</li><li><code>options</code> — rendering config: the dot-path key that <code>FormRenderer</code> uses to store the value (<code>options.label</code>), whether a field is required, min/max for scale inputs. This is what determines how the component is rendered, not what the user fills in.</li></ul><pre style=\"background:rgba(0,0,0,0.08);padding:14px;border-radius:6px;overflow-x:auto;font-size:0.85em;line-height:1.7\"><code>-- Querying JSONB in SQL:\nSELECT data->>''text'' AS label FROM components WHERE type = ''input'';\nSELECT * FROM components WHERE data @> ''{\"text\": \"Patient ID\"}''::jsonb;\n\n-- Updating a single JSONB key without overwriting the whole object:\nUPDATE components\n  SET data = data || ''{\"text\": \"Updated label\"}''::jsonb\n  WHERE id = $1::uuid;</code></pre><p>The <code>-&gt;&gt;</code> operator extracts a JSON value as text. <code>@&gt;</code> tests whether the left side contains the right side. The <code>||</code> operator merges two JSONB objects, with the right side winning on key conflicts.</p>"
  }', '{}'),

  ('00000000-0000-0000-0000-000000000222', 'db_uuids', 'contentHtml', '{
    "html": "<h2>UUID Conventions and Seeds</h2><p>Two categories of rows exist in the DB: <em>runtime rows</em> created by users through the app, and <em>seed rows</em> inserted by init scripts. They use UUIDs differently.</p><h3>Runtime rows</h3><p>Use <code>DEFAULT gen_random_uuid()</code> in the table definition. Postgres generates a fresh UUID on every INSERT. The application never needs to know the UUID in advance — it reads it back from the INSERT result or from a subsequent SELECT.</p><h3>Seed rows referenced from code</h3><p>Some seed rows are addressed by name or UUID from <code>constants.ts</code>. For example, <code>EDITOR_ID.DEFAULT = ''form_component_builder''</code> — when the Configuration page opens an edit modal it fetches the component tree named <code>form_component_builder</code>. If you ever change that name in the seed, the frontend constant must be updated too or the modal will silently fetch nothing.</p><p>For rows whose UUIDs are referenced directly from code, <strong>hardcode them in the seed</strong>. Use a recognisable prefix so they are easy to identify:</p><ul><li>Framework seeds: <code>c51c1e5f-5cc1-4b77-8832-2d10cc97XXXX</code></li><li>Content seeds: <code>00000000-0000-0000-0000-XXXXXXXXXXXX</code></li></ul><pre style=\"background:rgba(0,0,0,0.08);padding:14px;border-radius:6px;overflow-x:auto;font-size:0.85em;line-height:1.7\"><code>-- Good: hardcoded UUID for a seed row constants.ts depends on\nINSERT INTO components (id, name, type, data, options) VALUES\n  (''c51c1e5f-5cc1-4b77-8832-2d10cc970001'', ''form_my_feature'', ''form'', ..., ...)\nON CONFLICT (id) DO NOTHING;\n\n-- constants.ts:\nexport const FORM_ID = {\n  MY_FEATURE: ''form_my_feature'',\n} as const;</code></pre><p>The <code>ON CONFLICT (id) DO NOTHING</code> clause makes the INSERT idempotent — running <code>./run reset</code> multiple times won''t fail with duplicate key errors.</p>"
  }', '{}'),

  ('00000000-0000-0000-0000-000000000223', 'db_pool', 'contentHtml', '{
    "html": "<h2>Pool Queries and Transactions</h2><p>All database access goes through a <code>pg.Pool</code> instance exported from <code>nodejs/db.js</code>. A pool maintains a fixed number of open Postgres connections and hands them out to concurrent requests as needed. You never open or close connections manually.</p><pre style=\"background:rgba(0,0,0,0.08);padding:14px;border-radius:6px;overflow-x:auto;font-size:0.85em;line-height:1.7\"><code>const { pool } = require(''../../db'');\n\n// Simple query — returns { rows: [...], rowCount: N }\nconst { rows } = await pool.query(\n  ''SELECT * FROM my_things WHERE id = $1::uuid'',\n  [req.params.id]          // $1 is replaced by this value, safely\n);\n\n// Always use $1, $2, ... placeholders — NEVER string interpolation:\n// BAD:  pool.query(''SELECT * FROM things WHERE id = '' + req.params.id)\n// GOOD: pool.query(''SELECT * FROM things WHERE id = $1'', [req.params.id])\n</code></pre><p><strong>Why parameterized queries?</strong> String interpolation creates SQL injection vulnerabilities — an attacker can craft an input that modifies the query structure. The <code>$1</code> placeholder tells the Postgres driver to treat the value as data, never as SQL syntax, regardless of what it contains.</p><h3>Transactions</h3><p>When multiple queries must succeed or fail together — for example, inserting a component AND inserting its relationship row — use a transaction. If the second query fails, the first is rolled back automatically.</p><pre style=\"background:rgba(0,0,0,0.08);padding:14px;border-radius:6px;overflow-x:auto;font-size:0.85em;line-height:1.7\"><code>const client = await pool.connect();  // borrow a connection\ntry {\n  await client.query(''BEGIN'');\n  const { rows } = await client.query(\n    ''INSERT INTO my_things (name) VALUES ($1) RETURNING id'', [name]\n  );\n  await client.query(\n    ''INSERT INTO my_thing_tags (thing_id, tag) VALUES ($1, $2)'',\n    [rows[0].id, tag]\n  );\n  await client.query(''COMMIT'');\n  return rows[0];\n} catch (err) {\n  await client.query(''ROLLBACK'');\n  throw err;\n} finally {\n  client.release();  // return the connection to the pool\n}</code></pre><p>The <code>finally</code> block is critical — <code>client.release()</code> must always be called even if the query throws, otherwise the connection is leaked and the pool eventually starves.</p>"
  }', '{}')

ON CONFLICT (id) DO NOTHING;

