-- ── Dev Guide › Node.js Routes ────────────────────────────────────────────────

INSERT INTO components (id, name, type, data, options) VALUES

  ('00000000-0000-0000-0000-000000000230', 'node_router_setup', 'contentHtml', '{
    "html": "<h2>Router Setup and Registration</h2><p>Node.js REST routes are organised into files per domain resource. Each file creates an <code>express.Router()</code>, defines its routes, and exports the router. The router is then registered in <code>backend.js</code> under the <code>/api</code> prefix.</p><pre style=\"background:rgba(0,0,0,0.08);padding:14px;border-radius:6px;overflow-x:auto;font-size:0.85em;line-height:1.7\"><code>// nodejs/routes/myapp/things.js\nconst router = require(''express'').Router();\nconst { pool } = require(''../../db'');\n\nrouter.get(''/things'', async (req, res) =&gt; {\n  const { rows } = await pool.query(''SELECT * FROM my_things ORDER BY created_at DESC'');\n  res.json(rows);\n});\n\nrouter.get(''/things/:id'', async (req, res) =&gt; {\n  const { rows } = await pool.query(\n    ''SELECT * FROM my_things WHERE id = $1::uuid'', [req.params.id]\n  );\n  if (!rows.length) return res.status(404).json({ error: ''Not found'' });\n  res.json(rows[0]);\n});\n\nmodule.exports = router;</code></pre><p><strong>Why separate files?</strong> Each resource file is focused on one table or domain concept. When a bug appears in the things API you go to <code>routes/myapp/things.js</code> directly, not to a 2000-line monolith.</p><p>Registration in <code>backend.js</code>:</p><pre style=\"background:rgba(0,0,0,0.08);padding:14px;border-radius:6px;overflow-x:auto;font-size:0.85em;line-height:1.7\"><code>// backend.js — under // [MY DOMAIN]\nserver.use(''/api'', require(''./routes/myapp/things''));</code></pre><p>After this, <code>GET /api/things</code> and <code>GET /api/things/:id</code> are live. Express matches routes in registration order — register more specific routes (or a middleware for a sub-path) before general ones.</p>"
  }', '{}'),

  ('00000000-0000-0000-0000-000000000231', 'node_jwt_middleware', 'contentHtml', '{
    "html": "<h2>JWT Middleware</h2><p>A global middleware in <code>backend.js</code> runs on every request before any route handler. It reads the <code>Authorization</code> header, verifies the JWT, and attaches the decoded payload to <code>req.user</code>. Critically, it <strong>always calls <code>next()</code></strong> — it never blocks a request.</p><pre style=\"background:rgba(0,0,0,0.08);padding:14px;border-radius:6px;overflow-x:auto;font-size:0.85em;line-height:1.7\"><code>// From backend.js\nserver.use((req, res, next) =&gt; {\n  const auth = req.headers.authorization;\n  if (auth?.startsWith(''Bearer '')) {\n    try {\n      req.user = jwt.verify(auth.slice(7), process.env.JWT_SECRET);\n      //         ^--- decodes + verifies signature + checks exp claim\n      // legacy tokens carry only the role name — for the three\n      // system roles name === tier, so fall back\n      if (req.user &amp;&amp; !req.user.tier) req.user.tier = req.user.role;\n    } catch (_) {\n      req.user = null;  // expired, tampered, or wrong secret\n    }\n  } else {\n    req.user = null;  // no Authorization header\n  }\n  next();  // always continue — never block here\n});</code></pre><p><strong>What is <code>req.user</code>?</strong> If the token is valid, <code>req.user</code> contains the decoded payload: <code>{ id, email, role, tier, iat, exp }</code>. If the token is missing, expired, or invalid, <code>req.user</code> is <code>null</code>. The <code>tier</code> claim is the roles-table tier resolved at login (''registered'' &lt; ''user'' &lt; ''admin'') — <strong>every auth check compares the tier, never the role name</strong>; roles alias onto a tier via the <code>roles</code> table.</p><p><strong>Why always call next()?</strong> Tokenless routes (<code>/login</code>, <code>/register</code>) need to work without a token. Blocking in the middleware would require an allowlist. Instead, each route decides individually whether it needs auth:</p><pre style=\"background:rgba(0,0,0,0.08);padding:14px;border-radius:6px;overflow-x:auto;font-size:0.85em;line-height:1.7\"><code>// Require any authenticated user:\nrouter.post(''/things'', async (req, res) =&gt; {\n  if (!req.user) return res.status(401).json({ error: ''Login required'' });\n  // ... proceed\n});\n\n// Require admin tier:\nrouter.delete(''/things/:id'', async (req, res) =&gt; {\n  if (req.user?.tier !== ''admin'') return res.status(403).json({ error: ''Admin only'' });\n  // ... proceed\n});</code></pre>"
  }', '{}'),

  ('00000000-0000-0000-0000-000000000232', 'node_writing_routes', 'contentHtml', '{
    "html": "<h2>Writing Routes: POST, PUT, DELETE</h2><p>The consistent pattern for mutating routes: validate auth, parse the body, run parameterized SQL, return the result or an error.</p><pre style=\"background:rgba(0,0,0,0.08);padding:14px;border-radius:6px;overflow-x:auto;font-size:0.85em;line-height:1.7\"><code>// POST /api/things — create a new thing\nrouter.post(''/things'', async (req, res) =&gt; {\n  if (!req.user) return res.status(401).json({ error: ''Login required'' });\n\n  const { name, data = {} } = req.body;\n  if (!name) return res.status(400).json({ error: ''name is required'' });\n\n  try {\n    const { rows } = await pool.query(\n      `INSERT INTO my_things (name, data, created_by)\n       VALUES ($1, $2::jsonb, $3::uuid)\n       RETURNING *`,\n      [name, JSON.stringify(data), req.user.id]\n    );\n    res.status(201).json(rows[0]);\n  } catch (err) {\n    console.error(err);\n    res.status(500).json({ error: ''Database error'' });\n  }\n});</code></pre><p>Line by line:</p><ul><li><code>if (!req.user)</code> — guard: reject unauthenticated requests before touching the DB</li><li><code>const { name, data = {} } = req.body</code> — destructure the JSON body; <code>= {}</code> gives a safe default</li><li><code>if (!name)</code> — validate required fields at the application boundary; don''t let the DB constraint error be the first signal</li><li><code>$2::jsonb</code> — explicitly cast the parameter to JSONB; the pg driver sends it as a string, and the cast ensures Postgres stores it as structured JSON</li><li><code>RETURNING *</code> — returns the full inserted row including the generated <code>id</code> and <code>created_at</code>, so the frontend doesn''t need a separate SELECT</li><li><code>res.status(201)</code> — HTTP 201 Created for successful inserts; 200 OK is for reads and updates</li></ul><pre style=\"background:rgba(0,0,0,0.08);padding:14px;border-radius:6px;overflow-x:auto;font-size:0.85em;line-height:1.7\"><code>// DELETE /api/things/:id\nrouter.delete(''/things/:id'', async (req, res) =&gt; {\n  if (req.user?.tier !== ''admin'') return res.status(403).json({ error: ''Admin only'' });\n  const { rowCount } = await pool.query(\n    ''DELETE FROM my_things WHERE id = $1::uuid'', [req.params.id]\n  );\n  if (!rowCount) return res.status(404).json({ error: ''Not found'' });\n  res.json({ deleted: req.params.id });\n});</code></pre>"
  }', '{}'),

  ('00000000-0000-0000-0000-000000000233', 'node_file_upload', 'contentHtml', '{
    "html": "<h2>File Upload and MinIO</h2><p>The Files page uploads binary files to MinIO (S3-compatible object storage) and records metadata in the <code>files</code> Postgres table. The upload route in <code>routes/framework/files.js</code> demonstrates the pattern.</p><pre style=\"background:rgba(0,0,0,0.08);padding:14px;border-radius:6px;overflow-x:auto;font-size:0.85em;line-height:1.7\"><code>// Simplified upload handler\nconst multer  = require(''multer'');\nconst upload  = multer({ storage: multer.memoryStorage() });\nconst { minioClient, BUCKET } = require(''../../db'');\n\nrouter.post(''/files/upload'', upload.single(''file''), async (req, res) =&gt; {\n  if (req.user?.tier !== ''admin'') return res.status(403).json({ error: ''Admin only'' });\n\n  const { originalname, mimetype, size, buffer } = req.file;\n  const key = crypto.randomUUID();  // unique MinIO object key\n\n  // 1. Upload binary to MinIO\n  await minioClient.putObject(BUCKET, key, buffer, size, {\n    ''Content-Type'': mimetype,\n  });\n\n  // 2. Record metadata in Postgres\n  const { rows } = await pool.query(\n    `INSERT INTO files (key, filename, mimetype, size, uploaded_by)\n     VALUES ($1, $2, $3, $4, $5) RETURNING *`,\n    [key, originalname, mimetype, size, req.user.id]\n  );\n  res.status(201).json(rows[0]);\n});</code></pre><p><strong>multer memoryStorage</strong> — the file is buffered in RAM before being forwarded to MinIO. For very large files this could be a memory concern; in production you would stream directly from the request to MinIO without buffering.</p><p><strong>The download-by-key pattern</strong> — content cards reference files as <code>http://localhost:3000/api/files/&lt;key&gt;/download-by-key</code>. The download endpoint looks up the key in the files table, then streams the object from MinIO to the response with the correct Content-Type. This decouples the URL from the MinIO bucket structure and lets you move objects or change buckets without updating every content card.</p>"
  }', '{}')

ON CONFLICT (id) DO NOTHING;

