-- ── Dev Guide › Python ────────────────────────────────────────────────────────

INSERT INTO components (id, name, type, data, options) VALUES

  ('00000000-0000-0000-0000-000000000250', 'py_setup', 'contentHtml', '{
    "html": "<h2>FastAPI Setup</h2><p>The Python service is a FastAPI app running in its own container at <code>http://python:5000</code> (service name from docker-compose). It handles computation only — no DB connection, no state. Results flow back to Node.js which persists them.</p><pre style=\"background:rgba(0,0,0,0.08);padding:14px;border-radius:6px;overflow-x:auto;font-size:0.85em;line-height:1.7\"><code># python/api/main.py\nfrom fastapi import FastAPI\nfrom .domains.myapp.routes import router as myapp_router\n\napp = FastAPI()\napp.include_router(myapp_router)\n\n# python/api/domains/myapp/routes.py\nfrom fastapi import APIRouter\nfrom pydantic import BaseModel\n\nrouter = APIRouter()\n\nclass ComputeInput(BaseModel):\n    values: list[float]\n    param:  float\n\n@router.post(''/myapp/compute'')\ndef run_computation(payload: ComputeInput) -&gt; dict:\n    result = heavy_math(payload.values, payload.param)\n    return {''result'': result, ''status'': ''ok''}</code></pre><p>Pydantic models (<code>BaseModel</code>) validate and type-check the request body automatically. If the body is missing a required field or has the wrong type, FastAPI returns a 422 Unprocessable Entity with a detailed error message before your function is even called. This is the Python equivalent of Express''s manual <code>if (!req.body.name)</code> checks.</p><p>Add Python dependencies to <code>python/requirements.txt</code> and run <code>./run rebuild python</code> to reinstall them in the container.</p>"
  }', '{}'),

  ('00000000-0000-0000-0000-000000000251', 'py_calling_from_node', 'contentHtml', '{
    "html": "<h2>Calling Python from Node.js</h2><p>Node.js calls the Python service via Axios. The call can live in a REST route or a GraphQL resolver — whichever fits your data flow. Node.js then persists the result to Postgres.</p><pre style=\"background:rgba(0,0,0,0.08);padding:14px;border-radius:6px;overflow-x:auto;font-size:0.85em;line-height:1.7\"><code>// nodejs/routes/myapp/things.js\nconst axios = require(''axios'');\n\nrouter.post(''/things/:id/compute'', async (req, res) =&gt; {\n  if (!req.user) return res.status(401).json({ error: ''Login required'' });\n\n  // 1. Fetch input data from Postgres\n  const { rows } = await pool.query(\n    ''SELECT * FROM my_things WHERE id = $1::uuid'', [req.params.id]\n  );\n  if (!rows.length) return res.status(404).json({ error: ''Not found'' });\n\n  // 2. Call Python for computation\n  const { data: result } = await axios.post(\n    ''http://python:5000/myapp/compute'',\n    { values: rows[0].values, param: req.body.param }\n  );\n\n  // 3. Persist the result in Postgres\n  await pool.query(\n    ''UPDATE my_things SET result = $1::jsonb WHERE id = $2::uuid'',\n    [JSON.stringify(result), req.params.id]\n  );\n\n  res.json({ ...rows[0], result });\n});</code></pre><p><strong>Why does Node.js persist the result, not Python?</strong> The Python service has no DB connection by design. Keeping all DB writes in Node.js means there is one place where data changes happen, and one place to audit or roll back. Python is stateless and replaceable — you can swap the computation library, rewrite the algorithm, or scale Python independently without touching data persistence logic.</p><p><strong>Error handling</strong> — wrap the Axios call in a try/catch. If Python is unreachable (e.g. container not started) Axios throws a connection error. Return a 503 Service Unavailable to the frontend rather than a 500 Internal Server Error, so the client knows the issue is temporary.</p>"
  }', '{}')

ON CONFLICT (id) DO NOTHING;

