-- ── Dev Guide › Frontend ──────────────────────────────────────────────────────

INSERT INTO components (id, name, type, data, options) VALUES

  ('00000000-0000-0000-0000-000000000260', 'fe_pages_routing', 'contentHtml', '{
    "html": "<h2>Pages and Routing</h2><p>The frontend is an Ionic React SPA using React Router v5 via <code>IonReactRouter</code>. All routes are registered in <code>App.tsx</code> inside an <code>IonRouterOutlet</code>.</p><pre style=\"background:rgba(0,0,0,0.08);padding:14px;border-radius:6px;overflow-x:auto;font-size:0.85em;line-height:1.7\"><code>// App.tsx — add under // [MY DOMAIN]\n&lt;PrivateRoute  // requires any valid token\n  path={ROUTE.MY_THINGS}\n  exact={true}\n  component={MyThings}\n/&gt;\n\n// Or admin-only:\n&lt;AdminRoute\n  path={ROUTE.MY_ADMIN_PAGE}\n  exact={true}\n  component={MyAdminPage}\n/&gt;</code></pre><p><strong>PrivateRoute</strong> — redirects to <code>/signin</code> if <code>AuthContext</code> has no valid token. Use for features available to all authenticated users (e.g. surveys).</p><p><strong>AdminRoute</strong> — additionally checks <code>user.tier === ''admin''</code> and redirects to <code>/</code> if not. Use for backoffice features.</p><p><strong>No catch-all redirect.</strong> <code>IonRouterOutlet</code> manages its own route stack and a catch-all <code>&lt;Redirect&gt;</code> causes the router to loop. Unmatched paths render blank by design — add the route or don''t link to it.</p><p>Pages live in <code>pwa/src/pages/&lt;domain&gt;/MyThings.tsx</code> and use <code>SplitPageLayout</code> as their outer shell. Every page imports its nav items and panel config from <code>constants.ts</code>.</p>"
  }', '{}'),

  ('00000000-0000-0000-0000-000000000261', 'fe_constants', 'contentHtml', '{
    "html": "<h2>constants.ts</h2><p>All shared literals — route paths, panel configs, nav items, form IDs, component types — live in <code>pwa/src/constants.ts</code>. If a string appears in more than one file, or if changing it would require a DB migration, it belongs here.</p><pre style=\"background:rgba(0,0,0,0.08);padding:14px;border-radius:6px;overflow-x:auto;font-size:0.85em;line-height:1.7\"><code>// constants.ts — add under // [MY DOMAIN]\n\nexport const ROUTE = {\n  // existing routes...\n  MY_THINGS: ''/folder/MyThings'',   // must match App.tsx path\n} as const;\n\nexport const AREA_NAV = {\n  // existing...\n  MYAPP: [\n    { label: ''Things'',    route: ''/folder/MyThings'',    icon: ''cube''     },\n    { label: ''Analytics'', route: ''/folder/Analytics'',  icon: ''bar-chart'' },\n  ],\n} as const;\n\nexport const PANEL_CONFIG = {\n  // existing...\n  MY_THINGS_LIST: {\n    title: ''Things'', emptyMessage: ''No things yet.'',\n    add: { enabled: true, label: ''New Thing'' },\n    filter: {\n      text: { enabled: true, placeholder: ''Search...'' },\n      type: { enabled: false },\n    },\n  },\n} as const satisfies Record&lt;string, PanelConfig&gt;;\n\n// If your domain uses a seeded form (referenced by name from the DB):\nexport const FORM_ID = {\n  // existing...\n  MY_THING_DETAIL: ''form_my_thing_detail'',\n} as const;</code></pre><p>The <code>as const</code> annotation makes all values readonly literal types in TypeScript — you get type errors if you try to assign an arbitrary string where a specific route is expected. The <code>satisfies</code> keyword additionally validates the shape against <code>PanelConfig</code> without widening the type.</p>"
  }', '{}'),

  ('00000000-0000-0000-0000-000000000262', 'fe_api_service', 'contentHtml', '{
    "html": "<h2>Api.ts — the service layer</h2><p>All API calls go through <code>pwa/src/services/Api.ts</code>. GraphQL queries use <code>graphql-http</code>; REST calls use Axios. The JWT token is injected automatically from <code>AuthContext</code>.</p><pre style=\"background:rgba(0,0,0,0.08);padding:14px;border-radius:6px;overflow-x:auto;font-size:0.85em;line-height:1.7\"><code>// Using the GraphQL client (from Api.ts)\nconst things = await ApiService.query&lt;{ thingList: Thing[] }&gt;(`\n  query {\n    thingList {\n      id\n      name\n      data\n      created_at\n    }\n  }\n`);\n\n// Using the REST client (Axios)\nconst newThing = await ApiService.post(ENDPOINT.THINGS, { name, data });\n\n// FormRenderer fetch pattern (used everywhere a form tree is needed):\nconst formTree = await ApiService.getComponentByName(FORM_ID.MY_THING_DETAIL);\n// Then pass formTree to &lt;FormRenderer component={formTree} ... /&gt;</code></pre><p>Do not call <code>fetch()</code> or <code>axios</code> directly from page components. Centralising API calls in <code>Api.ts</code> means the auth header, base URL, and error handling are all in one place. If the API changes (e.g. you add request signing or move to HTTPS) you update one file.</p><p>The GraphQL client uses <code>graphql-http/lib/use/fetch</code> with the <code>GQL_URL</code> constant and injects the <code>Authorization: Bearer &lt;token&gt;</code> header from the auth context automatically. GraphQL errors (resolver-level) are distinguished from HTTP errors (network-level) — the client throws on both so callers use a standard <code>try/catch</code>.</p>"
  }', '{}')

ON CONFLICT (id) DO NOTHING;

