-- ── Dev Guide › Architecture ──────────────────────────────────────────────────

INSERT INTO components (id, name, type, data, options) VALUES

  ('00000000-0000-0000-0000-000000000270', 'arch_stack', 'contentHtml', '{
    "html": "<h2>Service Stack</h2><pre style=\"background:rgba(0,0,0,0.08);padding:16px;border-radius:6px;font-size:0.85em;line-height:1.7\">Browser\n  │\n  └─► pwa        React + Ionic + Vite         :8100\n        │\n        ├─► nodejs  Express + GraphQL          :3000\n        │     ├─► postgres  PostgreSQL          :5432\n        │     ├─► minio     Object Storage      :9000\n        │     └─► python    FastAPI (via Axios) :5000\n        │\n        └─► python  FastAPI (direct, rare)      :5000</pre><p>The frontend never writes directly to Python — it goes through Node.js, which calls Python and then persists the result to Postgres. Python has no DB connection and holds no state. This separation means Python can be restarted, scaled, or replaced without touching data persistence logic.</p>"
  }', '{}'),

  ('00000000-0000-0000-0000-000000000271', 'arch_component_tree', 'contentHtml', '{
    "html": "<h2>Component Tree System</h2><p>UI structure — forms, inputs, selects, charts — is stored as nodes in the <code>components</code> table with JSONB <code>data</code> and <code>options</code> columns. Parent-child ordering uses <code>components_relationships.position</code>. This is the core architectural pattern of the framework.</p><h3>Key pieces</h3><ul><li><strong>TreeEditor</strong> — admin UI for building and reordering trees (Configuration page)</li><li><strong>FormRenderer</strong> — fetches a named tree and renders it as a live form. Two modes: <code>app</code> (dot-path keys) and <code>survey</code> (UUID keys)</li><li><strong>ComponentForm</strong> — the edit modal for individual nodes, itself driven by a seeded form tree</li></ul><h3>Node types</h3><p><code>form</code> · <code>input</code> · <code>check</code> · <code>select</code> · <code>option</code> · <code>color</code> · <code>plot</code> · <code>plotGrid</code> · <code>richtext</code> · <code>filepicker</code></p><p>The survey system mirrors this with a completely separate table set (<code>survey_components</code> / <code>survey_components_relationships</code>). Survey type: <code>survey</code> · <code>text</code> · <code>number</code> · <code>date</code> · <code>textarea</code> · <code>check</code> · <code>select</code> · <code>option</code> · <code>scale</code>.</p>"
  }', '{}'),

  ('00000000-0000-0000-0000-000000000272', 'arch_content', 'contentHtml', '{
    "html": "<h2>Content / CMS System</h2><p>Content pages are <code>contentPage</code> nodes in the shared <code>components</code> table. The root node <code>content_menu</code> (UUID <code>00000000-0000-0000-0000-000000000001</code>) holds child pages shown as top-level tabs in <code>Landing.tsx</code>. Pages can hold sub-pages — Landing shows the first level as a secondary nav row.</p><h3>Card types</h3><ul><li><code>contentHtml</code> — <code>data.html</code> rendered via <code>dangerouslySetInnerHTML</code></li><li><code>contentImage</code> — <code>data.src</code> + <code>data.alt</code></li><li><code>contentHtmlImage</code> — HTML left column + image right column; <code>data.html</code> + <code>data.src</code></li><li><code>contentLatex</code> — <code>data.html</code> with KaTeX math rendering</li></ul><p>Page nav labels use the <code>data.text</code> field (not <code>data.title</code>). Regenerate the seed snapshot with <code>./dump-content.sh</code> after editing content through the UI.</p>"
  }', '{}'),

  ('00000000-0000-0000-0000-000000000273', 'arch_auth', 'contentHtml', '{
    "html": "<h2>Auth Architecture</h2><p>JWT-based. The token is stored in <code>localStorage</code> under <code>auth_token</code> and decoded client-side to avoid a round-trip on every render. On startup, <code>AuthContext</code> validates the stored token against <code>GET /api/me</code>. If the server confirms the token is invalid or the user is deactivated, the token is cleared and the user is logged out.</p><h3>Frontend route guards</h3><ul><li><code>PrivateRoute</code> — requires any valid token; redirects to <code>/signin</code> if absent or expired</li><li><code>AdminRoute</code> — requires <code>tier === ''admin''</code>; redirects non-admins to <code>/</code></li></ul><h3>Backend enforcement</h3><p>The JWT middleware decodes the token on every request and guarantees a <code>tier</code> claim (the roles-table tier resolved at login) — all auth checks compare the tier, never the role name. For REST routes, each handler checks <code>req.user</code> manually. For GraphQL, the permission gate in <code>schema/index.js</code> checks <strong>every top-level field</strong> of the executed operation against the <code>permissions.js</code> tier lists before any resolver runs — identically for queries and mutations, and everything not listed is admin-only by default. Resolvers never check auth themselves; they only owner-scope rows.</p>"
  }', '{}')

ON CONFLICT (id) DO NOTHING;

