-- ── Dev Guide › Component Reference ──────────────────────────────────────────

INSERT INTO components (id, name, type, data, options) VALUES

  ('00000000-0000-0000-0000-000000000280', 'cr_overview', 'contentHtml', '{
    "html": "<h2>Shell Components Overview</h2><p>All shell components live in <code>pwa/src/components/shell/</code>. Every domain page is built from these — never write layout from scratch. Form and modal components live in <code>pwa/src/components/forms/</code>.</p><h3>Shell</h3><ul><li><strong>SplitPageLayout</strong> — outer frame: left ResourcePanel + right content area</li><li><strong>AreaShell</strong> — right-side content area wrapper with title and optional action bar</li><li><strong>ResourcePanel</strong> — left-side list with search, type filter, selection, and Add button</li><li><strong>DataTable</strong> — sortable table for flat record lists with column type hints</li><li><strong>ModalShell</strong> — standardised modal wrapper (header + scrollable body + footer)</li><li><strong>TabPanel</strong> — horizontal tab switcher (IonSegment)</li><li><strong>EmptyState</strong> — consistent zero-data placeholder</li><li><strong>TreeEditor</strong> — drag-and-reorder tree for component and survey trees</li><li><strong>EChart</strong> — chart renderer: owned glue over the Apache ECharts engine; pass the echarts options object straight through</li></ul><h3>Forms</h3><ul><li><strong>FormRenderer</strong> — fetches and renders a named component tree as a live form</li><li><strong>ComponentForm</strong> — the edit modal for tree nodes; driven by seeded editor forms</li><li><strong>ImagePicker</strong> — MinIO file browser used inside form fields of type <code>filepicker</code></li><li><strong>ListModal</strong> — generic modal for picking an item from a searchable list</li><li><strong>RichTextEditor</strong> — inline HTML editor used for <code>contentHtml</code> and <code>richtext</code> component fields</li></ul>"
  }', '{}'),

  ('00000000-0000-0000-0000-000000000281', 'cr_splitpagelayout', 'contentHtmlImage', '{
    "html": "<h2>SplitPageLayout</h2><p>The outer frame for every authenticated page. Renders the sidebar nav, a <code>ResourcePanel</code> left column, and a right content area that scrolls independently. On narrow viewports the left panel collapses into a slide-in menu.</p><pre style=\"background:rgba(0,0,0,0.08);padding:12px;border-radius:6px;overflow-x:auto;font-size:0.85em;line-height:1.7\"><code>&lt;SplitPageLayout\n  navItems={AREA_NAV.MYAPP}\n  title=\"Things\"\n  rightHeader={&lt;IonButton onClick={openAdd}&gt;New Thing&lt;/IonButton&gt;}\n&gt;\n  {/* right-side content — e.g. a TabPanel */}\n&lt;/SplitPageLayout&gt;</code></pre><p><code>navItems</code> — array of <code>{ label, route, icon }</code> from <code>AREA_NAV</code> in <code>constants.ts</code>. Ionic icon names are used (e.g. <code>''cube''</code>, <code>''bar-chart''</code>).<br/><code>title</code> — shown in the <code>AreaShell</code> header above the right-side content.<br/><code>rightHeader</code> — optional JSX rendered in the top-right corner; used for action buttons or filter controls.</p>",
    "src": "http://localhost:3000/api/files/seed-app-config.png/download-by-key",
    "alt": "Configuration page showing SplitPageLayout structure"
  }', '{}'),

  ('00000000-0000-0000-0000-000000000282', 'cr_areashell', 'contentHtmlImage', '{
    "html": "<h2>AreaShell</h2><p>The right-side content area wrapper. Renders a header bar with the page title and optional action elements, and a scrollable content body below it. <code>SplitPageLayout</code> uses <code>AreaShell</code> internally — you rarely need to use it directly unless building a custom layout outside <code>SplitPageLayout</code>.</p><pre style=\"background:rgba(0,0,0,0.08);padding:12px;border-radius:6px;overflow-x:auto;font-size:0.85em;line-height:1.7\"><code>&lt;AreaShell\n  title=\"Things\"\n  actions={&lt;IonButton size=\"small\"&gt;Export&lt;/IonButton&gt;}\n&gt;\n  &lt;DataTable columns={cols} rows={rows} /&gt;\n&lt;/AreaShell&gt;</code></pre><p>The <code>title</code> is displayed as a bold heading in the area header bar. <code>actions</code> renders to the right of the title — suitable for buttons, badges, or status indicators. The slot below the header scrolls independently from the rest of the page.</p>",
    "src": "http://localhost:3000/api/files/seed-app-config.png/download-by-key",
    "alt": "AreaShell header with title and action button"
  }', '{}'),

  ('00000000-0000-0000-0000-000000000283', 'cr_resourcepanel', 'contentHtmlImage', '{
    "html": "<h2>ResourcePanel</h2><p>The left-side list panel. Handles text search, type filtering, selection highlight, and the Add button through a static config object — the page only provides items and callbacks.</p><pre style=\"background:rgba(0,0,0,0.08);padding:12px;border-radius:6px;overflow-x:auto;font-size:0.85em;line-height:1.7\"><code>&lt;ResourcePanel\n  config={PANEL_CONFIG.MY_THINGS_LIST}\n  items={things.map(t =&gt; ({ id: t.id, name: t.name, type: t.kind }))}\n  selectedId={selectedId}\n  onSelect={id =&gt; setSelectedId(id)}\n  onAdd={() =&gt; setShowAddModal(true)}\n/&gt;</code></pre><p>Define the config in <code>PANEL_CONFIG</code> in <code>constants.ts</code>. The config controls: panel title, empty message, Add button label and visibility, text search placeholder and visibility, and type dropdown options. Items must have shape <code>{ id, name, type? }</code>. The currently selected item is highlighted; clicking a new item calls <code>onSelect</code> with its id.</p>",
    "src": "http://localhost:3000/api/files/seed-app-config.png/download-by-key",
    "alt": "ResourcePanel showing the left component list"
  }', '{}'),

  ('00000000-0000-0000-0000-000000000284', 'cr_datatable', 'contentHtmlImage', '{
    "html": "<h2>DataTable</h2><p>A sortable table for flat record arrays. Column definitions declare the label and an optional type hint that controls cell rendering. Row actions (Edit, Delete, custom) are declared per-row via a callback.</p><pre style=\"background:rgba(0,0,0,0.08);padding:12px;border-radius:6px;overflow-x:auto;font-size:0.85em;line-height:1.7\"><code>&lt;DataTable\n  columns={[\n    { key: ''name'',       label: ''Name'' },\n    { key: ''role'',       label: ''Role'',  type: ''badge'' },\n    { key: ''active'',     label: ''Active'', type: ''boolean'' },\n    { key: ''created_at'', label: ''Date'',   type: ''date'' },\n  ]}\n  rows={users}\n  actions={row =&gt; [\n    { label: ''Edit'',       onClick: () =&gt; openEdit(row) },\n    { label: ''Deactivate'', onClick: () =&gt; toggle(row.id), color: ''warning'' },\n    { label: ''Delete'',     onClick: () =&gt; del(row.id),    color: ''danger'' },\n  ]}\n/&gt;</code></pre><p>Type hints: <code>date</code> formats as <code>YYYY-MM-DD HH:MM</code> · <code>badge</code> renders as an <code>IonBadge</code> with colour based on value · <code>boolean</code> renders as a checkmark or dash. The default renders plain text. Actions are buttons in a trailing column; <code>color</code> maps to Ionic colour names (<code>primary</code>, <code>warning</code>, <code>danger</code>).</p>",
    "src": "http://localhost:3000/api/files/seed-app-surveys-answers.png/download-by-key",
    "alt": "DataTable showing survey answers with column headers"
  }', '{}'),

  ('00000000-0000-0000-0000-000000000285', 'cr_modalshell', 'contentHtmlImage', '{
    "html": "<h2>ModalShell</h2><p>A standardised modal wrapper that provides a consistent header, scrollable content area, and footer action buttons. Every modal in the framework uses it — the New Survey modal, the Edit Component modal, the Create User modal.</p><pre style=\"background:rgba(0,0,0,0.08);padding:12px;border-radius:6px;overflow-x:auto;font-size:0.85em;line-height:1.7\"><code>&lt;ModalShell\n  isOpen={showModal}\n  title=\"New Thing\"\n  onClose={() =&gt; setShowModal(false)}\n  footer={\n    &lt;&gt;\n      &lt;IonButton fill=\"outline\" onClick={() =&gt; setShowModal(false)}&gt;Cancel&lt;/IonButton&gt;\n      &lt;IonButton onClick={handleSave} disabled={saving}&gt;\n        {saving ? &lt;IonSpinner name=\"dots\" /&gt; : ''Save''}\n      &lt;/IonButton&gt;\n    &lt;/&gt;\n  }\n&gt;\n  &lt;FormRenderer component={formTree} onSubmit={handleSave} /&gt;\n&lt;/ModalShell&gt;</code></pre><p><code>title</code> — shown in the modal header bar with a close (×) button.<br/><code>onClose</code> — called by both the × button and a backdrop click.<br/><code>footer</code> — JSX rendered in the sticky footer; conventionally Cancel on the left and Save/Submit on the right.</p>",
    "src": "http://localhost:3000/api/files/seed-comp-modal.png/download-by-key",
    "alt": "ModalShell with a form inside"
  }', '{}'),

  ('00000000-0000-0000-0000-000000000286', 'cr_tabpanel', 'contentHtmlImage', '{
    "html": "<h2>TabPanel</h2><p>A horizontal tab switcher built on <code>IonSegment</code>. Tab definitions declare a label, the content to render when the tab is active, and an optional actions strip shown below the tab bar. Supports both uncontrolled (internal state) and controlled (parent-managed) modes.</p><pre style=\"background:rgba(0,0,0,0.08);padding:12px;border-radius:6px;overflow-x:auto;font-size:0.85em;line-height:1.7\"><code>&lt;TabPanel\n  tabs={[\n    {\n      label: ''Fill Form'',\n      content: &lt;SurveyForm /&gt;,\n    },\n    {\n      label: ''Answers'',\n      content: &lt;AnswersTable /&gt;,\n      actions: &lt;IonButton size=\"small\"&gt;Export CSV&lt;/IonButton&gt;,\n    },\n    {\n      label: ''Build'',\n      content: &lt;TreeEditor ... /&gt;,\n      keepMounted: true,  // keeps TreeEditor in DOM when tab is inactive\n    },\n  ]}\n/&gt;</code></pre><p><code>actions</code> — rendered between the tab bar and the tab content; useful for buttons scoped to that tab (export, add, filter). <code>keepMounted: true</code> keeps the tab''s DOM alive even when it is not the active tab — essential for components with internal state or imperative refs (like <code>TreeEditor</code>) that would reset if remounted.</p>",
    "src": "http://localhost:3000/api/files/seed-app-surveys-fill.png/download-by-key",
    "alt": "TabPanel showing Fill Form / Answers / Build tabs"
  }', '{}'),

  ('00000000-0000-0000-0000-000000000287', 'cr_emptystate', 'contentHtmlImage', '{
    "html": "<h2>EmptyState</h2><p>A centred placeholder shown when a list is empty, nothing is selected, or a feature requires data that doesn''t exist yet. Provides a consistent look across all pages for zero-data states.</p><pre style=\"background:rgba(0,0,0,0.08);padding:12px;border-radius:6px;overflow-x:auto;font-size:0.85em;line-height:1.7\"><code>&lt;EmptyState\n  message=\"Select a component to preview\"\n/&gt;\n\n// Or with a call-to-action:\n&lt;EmptyState\n  message=\"No things yet.\"\n  action={&lt;IonButton onClick={openAdd}&gt;Create your first thing&lt;/IonButton&gt;}\n/&gt;</code></pre><p><code>message</code> — descriptive text telling the user what is missing or what to do. Keep it specific: <em>''Select a survey to view its answers''</em> is more helpful than <em>''No data''</em>. The optional <code>action</code> renders a button directly below the message — useful as a shortcut when the fix is obvious (create the first item, complete the setup step).</p>",
    "src": "http://localhost:3000/api/files/seed-comp-empty.png/download-by-key",
    "alt": "EmptyState placeholder"
  }', '{}'),

  ('00000000-0000-0000-0000-000000000288', 'cr_treeeditor', 'contentHtmlImage', '{
    "html": "<h2>TreeEditor</h2><p>The admin UI for building component and survey trees. Renders nodes recursively; each node shows its type badge and label with Edit, Delete, and Add-child buttons. Nodes can be reordered by dragging.</p><pre style=\"background:rgba(0,0,0,0.08);padding:12px;border-radius:6px;overflow-x:auto;font-size:0.85em;line-height:1.7\"><code>&lt;TreeEditor\n  root={selectedComponent}\n  onEdit={node =&gt; openEditModal(node)}\n  onDelete={async nodeId =&gt; {\n    await ApiService.deleteRelation(parentId, nodeId);\n    await ApiService.deleteComponent(nodeId);\n    reload();\n  }}\n  onReorder={async (parentId, childId, newPos) =&gt; {\n    await ApiService.updateRelationPosition(parentId, childId, newPos);\n  }}\n  onAdd={parentNode =&gt; openAddModal(parentNode)}\n/&gt;</code></pre><p><strong>Edit</strong> — opens a modal pre-filled with the node''s current <code>data</code> and <code>options</code>. <strong>Delete</strong> — removes the node and all its descendants; the callback should delete both the component record and its relationship row. <strong>Add</strong> — opens a modal to create a child; the callback receives the parent node so you know where to attach the new child. <strong>Reorder</strong> — called on drag-drop with the new integer position; updates <code>components_relationships.position</code>. The Link button attaches an existing node as a child without duplicating it.</p>",
    "src": "http://localhost:3000/api/files/seed-app-surveys-build.png/download-by-key",
    "alt": "TreeEditor showing a survey question tree"
  }', '{}'),

  ('00000000-0000-0000-0000-000000000289', 'cr_formrenderer', 'contentHtmlImage', '{
    "html": "<h2>FormRenderer</h2><p>Fetches a named component tree from the DB and renders it as a live, typed form. Two modes control how submitted values are keyed:</p><ul><li><code>mode=\"app\"</code> — dot-path keys (<code>section.fieldName</code>) derived from <code>options.label</code> on each node. Used for domain configuration forms and backoffice modals.</li><li><code>mode=\"survey\"</code> — UUID keys (<code>node.id</code>). Used for survey fill-in and editing. Answers remain queryable even if field labels change.</li></ul><pre style=\"background:rgba(0,0,0,0.08);padding:12px;border-radius:6px;overflow-x:auto;font-size:0.85em;line-height:1.7\"><code>// Fetch the tree once, then pass to the renderer\nconst [formTree, setFormTree] = useState(null);\nuseEffect(() =&gt; {\n  ApiService.getComponentByName(FORM_ID.MY_THING_DETAIL).then(setFormTree);\n}, []);\n\n// In the JSX:\n{formTree &amp;&amp; (\n  &lt;FormRenderer\n    component={formTree}\n    defaultValues={existingValues}  // pre-fill for edit flows\n    onSubmit={async (values) =&gt; {\n      // values is { ''section.field'': value, ... } in app mode\n      await ApiService.post(ENDPOINT.THINGS, values);\n    }}\n    submitLabel=\"Save\"\n  /&gt;\n)}</code></pre><p><code>defaultValues</code> pre-fills the form for edit flows — pass the existing record''s values in the same shape the form would submit. The renderer matches keys to fields. <code>submitLabel</code> overrides the default ''Submit'' button text. All validation (required fields, numeric types) is handled by the renderer based on the component tree definition.</p>",
    "src": "http://localhost:3000/api/files/seed-app-surveys-fill.png/download-by-key",
    "alt": "FormRenderer rendering a live survey form"
  }', '{}'),

  ('00000000-0000-0000-0000-000000000290', 'cr_richtexteditor', 'contentHtmlImage', '{
    "html": "<h2>RichTextEditor</h2><p>An inline HTML editor used for <code>contentHtml</code> content cards and for <code>richtext</code> component type fields. Wraps a WYSIWYG editor that produces clean HTML output stored in <code>data.html</code>.</p><p>The editor is embedded directly in the Content → Build tab when you add or edit an HTML card. You type and format in the editor; on save, the HTML string is written to the component''s <code>data.html</code> JSONB field and rendered immediately by <code>ContentRenderer</code> on the public page.</p><p>For <code>richtext</code> components in configuration trees (used for notes or description fields in domain forms), <code>FormRenderer</code> embeds the editor inline in the form. The submitted value is a raw HTML string stored in the form''s value map.</p>",
    "src": "http://localhost:3000/api/files/seed-comp-richtext.png/download-by-key",
    "alt": "RichTextEditor open for editing an HTML card"
  }', '{}'),

  ('00000000-0000-0000-0000-000000000291', 'cr_imagepicker', 'contentHtmlImage', '{
    "html": "<h2>ImagePicker</h2><p>A MinIO file browser embedded in forms wherever an image URL is needed. Used for <code>contentImage</code> and <code>contentHtmlImage</code> content cards, and for <code>filepicker</code> component type fields in configuration forms.</p><p>When a form field is type <code>filepicker</code>, <code>FormRenderer</code> renders an <strong>ImagePicker</strong> instead of a text input. The picker opens a modal listing all files from the <code>files</code> table, with thumbnail previews for images and file-type badges for other formats. Selecting a file sets the field value to the file''s <code>download-by-key</code> URL — the same URL pattern used by content cards.</p><p>This keeps the workflow consistent: upload a file once via the Files page, then reference it anywhere in the app — content cards, form fields, domain models — by picking it from the ImagePicker.</p>",
    "src": "http://localhost:3000/api/files/seed-comp-imagepicker.png/download-by-key",
    "alt": "ImagePicker showing MinIO file browser"
  }', '{}')

ON CONFLICT (id) DO NOTHING;

