-- ── Dev Guide › Claude Code Integration ──────────────────────────────────────

INSERT INTO components (id, name, type, data, options) VALUES

  ('00000000-0000-0000-0000-000000000300', 'cc_setup', 'contentHtml', '{
    "html": "<h2>Setting Up Claude Code</h2><p>Claude Code is Anthropic''s official CLI and IDE integration for AI-assisted development. It reads the <code>CLAUDE.md</code> file at the project root to understand the codebase before touching any code — making it well-suited for ManuSpine where the domain conventions are consistent and worth explaining once.</p><h3>Install</h3><pre style=\"background:rgba(0,0,0,0.08);padding:14px;border-radius:6px;overflow-x:auto;font-size:0.85em;line-height:1.7\"><code>npm install -g @anthropic-ai/claude-code\ncd /path/to/manuspine\nclaude    # starts an interactive session with project context loaded</code></pre><p>Claude Code is also available as a desktop app (Mac / Windows), a web app at <a href=\"https://claude.ai/code\">claude.ai/code</a>, and as VS Code and JetBrains IDE extensions. The CLI, desktop, and IDE extensions all work the same way — they read <code>CLAUDE.md</code> on startup and keep the conversation context across your session.</p><h3>API key</h3><p>Claude Code uses <code>ANTHROPIC_API_KEY</code> from your environment. The same key powers the AI Import feature in the Backoffice. Set it once in your shell profile or in <code>.env</code> and both features will work.</p><h3>Current model IDs</h3><ul><li><code>claude-opus-4-7</code> — most capable; best for complex, multi-file domain scaffolding</li><li><code>claude-sonnet-4-6</code> — fast and balanced; good for iterative edits and code review</li><li><code>claude-haiku-4-5</code> — fastest; good for short completions and boilerplate generation</li></ul>"
  }', '{}'),

  ('00000000-0000-0000-0000-000000000301', 'cc_claude_md', 'contentHtml', '{
    "html": "<h2>The CLAUDE.md File</h2><p><code>CLAUDE.md</code> sits at the repo root and is read automatically at the start of every Claude Code session. It is the contract between the codebase and the AI — instead of re-explaining conventions every time, you document them once and Claude follows them.</p><h3>What it covers for this project</h3><ul><li><strong>Running commands</strong> — always <code>./run</code>, never raw <code>docker compose</code>. The reason is in the file: <code>./run</code> passes <code>UID</code>/<code>GID</code> so container-written files stay owned by you, not root.</li><li><strong>Architecture</strong> — the five-layer domain pattern, the component tree system, the content/CMS structure, the survey system. Claude reads this to understand the project holistically before touching any file.</li><li><strong>Domain conventions</strong> — where to add files, which comments to use (<code>// [MY DOMAIN]</code> / <code>-- [MY DOMAIN]</code>), UUID seeding rules, the <code>ON CONFLICT (id) DO NOTHING</code> pattern.</li><li><strong>Service URLs</strong> — frontend, GraphQL playground, Python service — so Claude can tell you where to check a change without you having to look it up.</li></ul><h3>Extending it</h3><p>Add project-specific decisions, constraints, or context that you would otherwise repeat every session. Which tables are write-heavy. Which components need special handling. Which third-party integrations are in play. The file is committed to the repo so it stays in sync with the codebase and every developer gets the same AI behaviour.</p><p>The <code>.claude/</code> directory (per-developer auto-memory and session logs) is gitignored — it is personal to each machine and should not be committed.</p>"
  }', '{}'),

  ('00000000-0000-0000-0000-000000000302', 'cc_domain_dev', 'contentHtml', '{
    "html": "<h2>Developing Domains with Claude Code</h2><p>The consistent five-layer domain pattern is what makes ManuSpine AI-friendly. Because every domain follows the same structure, Claude can scaffold an entire domain end-to-end from a single description — SQL, REST routes, GraphQL, and a React page.</p><h3>Example prompt</h3><pre style=\"background:rgba(0,0,0,0.08);padding:14px;border-radius:6px;overflow-x:auto;font-size:0.85em;line-height:1.7\"><code>Add a Patient domain. Fields: name (text), date_of_birth (date),\ndiagnosis (text), notes (richtext). Admin-only.\nLeft panel lists patients by name. Right panel shows a FormRenderer\ndetail view with edit and delete. Follow the ManuSpine domain\npattern from CLAUDE.md.</code></pre><p>Claude Code will work through each layer in order:</p><ol><li>Create <code>init-scripts/02-init-patients.sql</code> with the table and seeded form tree</li><li>Add <code>nodejs/routes/patients/patients.js</code> with list, get, create, update, delete</li><li>Register the router in <code>backend.js</code> under the <code>// [MY DOMAIN]</code> comment</li><li>Add GraphQL types and resolvers in <code>schema/resolvers/patients/</code></li><li>Spread resolvers into <code>schema/index.js</code></li><li>Create the React page using <code>SplitPageLayout</code> + <code>ResourcePanel</code> + <code>FormRenderer</code></li><li>Add the route in <code>App.tsx</code>, nav entry in <code>Menu.tsx</code>, and constants in <code>constants.ts</code></li></ol><h3>Tips</h3><ul><li>Mention which shell components to use — Claude will look them up in the Component Reference section</li><li>For seeded form trees, tell Claude which UUIDs need to be hardcoded (those referenced from <code>constants.ts</code>)</li><li>After scaffolding, run <code>./run reset</code> to apply the SQL on a fresh volume and verify the domain end-to-end</li><li>Claude Code tracks what it has changed across the session — ask it to summarise before committing</li></ul>"
  }', '{}'),

  ('00000000-0000-0000-0000-000000000303', 'cc_resources', 'contentHtml', '{
    "html": "<h2>Resources and Links</h2><h3>Claude Code</h3><ul><li><a href=\"https://claude.ai/code\">claude.ai/code</a> — web app, desktop download, and IDE extension links</li><li><a href=\"https://github.com/anthropics/claude-code\">github.com/anthropics/claude-code</a> — issues, feature requests, community discussions</li></ul><h3>Anthropic API</h3><p>Both Claude Code and the AI Import feature use the Anthropic API via <code>ANTHROPIC_API_KEY</code>. You do not need a separate key for each — set it once.</p><ul><li><a href=\"https://docs.anthropic.com\">docs.anthropic.com</a> — API reference, model guides, prompt engineering docs</li></ul><h3>AI Import</h3><p>The AI Import feature is pre-wired to call Claude through the Node.js backend — no extra configuration beyond the API key. It keeps the conversation history in <code>localStorage</code> so long editing sessions survive page refreshes. See <strong>App Guide → Backoffice → AI Import</strong> for the full workflow.</p><h3>Getting help with Claude Code</h3><p>Run <code>/help</code> inside a Claude Code session to see available commands. Report issues at <a href=\"https://github.com/anthropics/claude-code/issues\">github.com/anthropics/claude-code/issues</a>. For framework-specific questions, Claude Code already has the full project context from <code>CLAUDE.md</code> — just ask.</p>"
  }', '{}')

ON CONFLICT (id) DO NOTHING;

