-- ── App Guide › Survey — Stats tab card (position 5) ────────────────────────

INSERT INTO components (id, name, type, data, options) VALUES
  ('00000000-0000-0000-0000-000000000125', 'survey_stats', 'contentHtmlImage', '{
    "html": "<h2>Stats</h2><p>Admin-only tab. When a survey contains numeric questions, the Stats tab runs a live pandas analysis over all submitted answers and displays one statistics card per numeric question.</p><h3>Per-question card</h3><ul><li><strong>Descriptive statistics</strong> — count, mean, standard deviation, min, 25th/50th/75th percentile, and max; computed by <code>df.describe()</code> on the full answer set</li><li><strong>Clinical range</strong> — for recognised vital sign questions the expected normal bounds are shown (e.g. SpO₂ 95–100%). The card border turns red and an abnormal-readings counter appears when values fall outside the range</li><li><strong>IQR outliers</strong> — individual values beyond Q1 − 1.5×IQR or Q3 + 1.5×IQR are listed as warning chips</li></ul><h3>Actions</h3><p><strong>Refresh</strong> re-runs the analysis after new answers have been submitted. <strong>Export CSV</strong> downloads a flat file of all answers for the selected survey — one row per submission, one column per question — via a streaming Node.js endpoint backed by <code>pandas df.to_csv()</code>.</p><h3>How it works</h3><p>The frontend sends the survey ID to a GraphQL resolver. Node.js fetches the full question tree via a recursive CTE and all submitted answers from Postgres, then POSTs both to the Python service. Python builds a pandas DataFrame and returns descriptive stats, IQR outliers, and clinical range checks as JSON. Node.js forwards this to the frontend unchanged. The full technical walkthrough is in <strong>Developer Guide → Layers → Python</strong>.</p>",
    "src": "http://localhost:3000/api/files/seed-app-surveys-stats.png/download-by-key",
    "alt": "Stats tab showing pandas analytics cards per numeric survey question"
  }', '{}')
ON CONFLICT (id) DO NOTHING;

